CREATE DATABASE IF NOT EXISTS campus_careertrack CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE campus_careertrack;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('student','admin') NOT NULL DEFAULT 'student',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS student_profiles (user_id INT UNSIGNED PRIMARY KEY,department VARCHAR(120) NOT NULL DEFAULT '',year_of_study VARCHAR(30) NOT NULL DEFAULT '',graduation_year SMALLINT NULL,skills VARCHAR(500) NOT NULL DEFAULT '',career_objective VARCHAR(1000) NOT NULL DEFAULT '',FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS opportunities (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,company VARCHAR(150) NOT NULL,type ENUM('Internship','Full-time','Part-time') NOT NULL DEFAULT 'Internship',location VARCHAR(150) NOT NULL DEFAULT 'Not specified',work_mode ENUM('Remote','Hybrid','On-site') NOT NULL DEFAULT 'Hybrid',compensation VARCHAR(100) NOT NULL DEFAULT '',skills VARCHAR(255) NOT NULL DEFAULT '',description TEXT NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,created_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS applications (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,opportunity_id INT UNSIGNED NOT NULL,cover_letter VARCHAR(500) NOT NULL,status ENUM('Pending','Shortlisted','Interview','Offer','Rejected') NOT NULL DEFAULT 'Pending',applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY unique_user_opportunity(user_id,opportunity_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(opportunity_id) REFERENCES opportunities(id) ON DELETE CASCADE) ENGINE=InnoDB;
INSERT INTO opportunities(title,company,type,location,work_mode,compensation,skills,description) SELECT 'Frontend Developer Intern','BrightPixel Labs','Internship','Coimbatore','Hybrid','₹8,000–₹12,000 / month','HTML, CSS, JavaScript, React','Build accessible interfaces and collaborate with the product team.' WHERE NOT EXISTS (SELECT 1 FROM opportunities WHERE title='Frontend Developer Intern' AND company='BrightPixel Labs');
INSERT INTO opportunities(title,company,type,location,work_mode,compensation,skills,description) SELECT 'Junior Java Developer','NexaSoft Solutions','Full-time','Chennai','On-site','₹3.5–5 LPA','Java, SQL, OOP, Git','Assist with Java application development, testing, and maintenance.' WHERE NOT EXISTS (SELECT 1 FROM opportunities WHERE title='Junior Java Developer' AND company='NexaSoft Solutions');
INSERT INTO opportunities(title,company,type,location,work_mode,compensation,skills,description) SELECT 'Data Analyst Intern','InsightSpring','Internship','Remote','Remote','₹10,000 / month','Python, SQL, Excel, Power BI','Prepare datasets, build dashboards, and communicate useful insights.' WHERE NOT EXISTS (SELECT 1 FROM opportunities WHERE title='Data Analyst Intern' AND company='InsightSpring');
INSERT INTO opportunities(title,company,type,location,work_mode,compensation,skills,description) SELECT 'PHP Web Developer Intern','WebNest Studio','Internship','Coimbatore','On-site','₹6,000–₹9,000 / month','PHP, MySQL, HTML, CSS','Develop and test database-backed web features under mentor guidance.' WHERE NOT EXISTS (SELECT 1 FROM opportunities WHERE title='PHP Web Developer Intern' AND company='WebNest Studio');
